/**
 * Builds SSLContext instances for ADB TLS connections using the persisted ADB RSA key pair.
 *
 * ADB's wireless debugging uses mutual TLS where both client and server present self-signed
 * certificates. The server does not validate the certificate chain — it identifies clients
 * by RSA public key registered during pairing. This factory builds the SSLContext so the
 * presented certificate carries the correct ADB RSA key.
 *
 * The trust-all TrustManager is intentional: the ADB daemon uses a self-signed cert, and
 * identity is verified through the SPAKE2 pairing protocol, not the TLS certificate chain.
 */
final class AdbTlsContext {

    private AdbTlsContext() {}

    /**
     * Creates a TLSv1.3 SSLContext using the given ADB RSA private key.
     *
     * Generates a self-signed X.509 certificate from the key (CN=00, matching adbd convention)
     * and configures a trust-all TrustManager since ADB verifies identity via its own protocol.
     *
     * @param privateKey the ADB RSA private key (from the persisted adbkey file)
     * @return SSLContext configured for ADB TLS connections
     * @throws RuntimeException if certificate generation or SSLContext initialization fails
     */
    static SSLContext create(PrivateKey privateKey) {
        return create(privateKey, null);
    }

    /**
     * Creates a TLSv1.3 SSLContext using a specific security Provider.
     *
     * When {@code provider} is non-null, the SSLContext is obtained from that provider.
     * This is required for ADB pairing: the standalone Conscrypt provider creates SSLSockets
     * that support {@code exportKeyingMaterial()} (RFC 5705), which Android's platform
     * Conscrypt blocks via hidden-API restrictions for targetSdk 35+.
     *
     * @param privateKey the ADB RSA private key
     * @param provider   security Provider for SSLContext, or null for the system default
     * @return SSLContext configured for ADB TLS connections
     * @throws RuntimeException if certificate generation or SSLContext initialization fails
     */
    static SSLContext create(PrivateKey privateKey, Provider provider) {
        try {
            // Derive the public key from the RSA private key
            RSAPrivateKey rsaPrivate = (RSAPrivateKey) privateKey;
            PublicKey publicKey = KeyFactory.getInstance("RSA")
                    .generatePublic(new RSAPublicKeySpec(
                            rsaPrivate.getModulus(),
                            BigInteger.valueOf(65537))); // F4

            // Self-signed cert matching adbd's expectations: CN=00, far-future expiry
            ContentSigner signer = new JcaContentSignerBuilder("SHA256withRSA")
                    .build(privateKey);

            X509v3CertificateBuilder certBuilder = new X509v3CertificateBuilder(
                    new X500Name("CN=00"),
                    BigInteger.ONE,
                    new Date(0),
                    new Date(2461449600L * 1000), // ~2048
                    Locale.ROOT,
                    new X500Name("CN=00"),
                    SubjectPublicKeyInfo.getInstance(publicKey.getEncoded()));

            X509Certificate cert = (X509Certificate) CertificateFactory.getInstance("X.509")
                    .generateCertificate(new ByteArrayInputStream(
                            certBuilder.build(signer).getEncoded()));

            // KeyManager that always returns our ADB key + cert
            KeyManager keyManager = new AdbKeyManager(privateKey, cert);

            // Trust-all: ADB uses its own auth protocol, not CA-based PKI.
            TrustManager trustAll = new X509TrustManager() {
                @Override public void checkClientTrusted(X509Certificate[] c, String t) {}
                @Override public void checkServerTrusted(X509Certificate[] c, String t) {}
                @Override public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
            };

            SSLContext ctx = provider != null
                    ? SSLContext.getInstance("TLSv1.3", provider)
                    : SSLContext.getInstance("TLSv1.3");
            ctx.init(new KeyManager[]{keyManager}, new TrustManager[]{trustAll}, new SecureRandom());
            return ctx;

        } catch (Exception e) {
            throw new RuntimeException("Failed to create ADB TLS context", e);
        }
    }

