package app.reverb.track.device.advanced.adb;

import android.util.Log;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocket;

/**
 * Handles ADB TLS upgrades for wireless debugging connections on Android 11+.
 *
 * Wireless debugging ports advertised via mDNS (_adb-tls-connect._tcp.) require a
 * TLS upgrade (A_STLS) before normal ADB protocol can proceed:
 *
 * <ol>
 *   <li>Client sends A_CNXN on the plain socket</li>
 *   <li>Server responds with A_STLS</li>
 *   <li>Client sends A_STLS acknowledgement</li>
 *   <li>Both sides perform a TLS handshake → SSLSocket (transport encryption)</li>
 *   <li>Server verifies client certificate against paired keys</li>
 *   <li>Server sends A_CNXN through TLS — connection is AUTHENTICATED and ONLINE</li>
 * </ol>
 *
 * <h3>Why there is no "Phase 2"</h3>
 * The daemon authenticates the client during the TLS handshake itself via mutual
 * certificate verification (the RSA key registered during pairing is presented as a
 * client certificate). After the handshake, the daemon calls
 * {@code adbd_wifi_secure_connect → handle_online → send_connect}, sending A_CNXN
 * through TLS. The connection is fully established at this point.
 *
 * <p>Sending another A_CNXN after TLS would trigger {@code handle_new_connection} on
 * the daemon, which calls {@code handle_offline(t)} (resetting the transport!) followed
 * by {@code send_tls_request(t)} (sending A_STLS again). The standard ADB host client
 * avoids this by never sending A_CNXN after the TLS handshake — it only receives the
 * daemon's A_CNXN and transitions to ONLINE.
 *
 * <p>This class captures the daemon's post-auth A_CNXN (with version, maxPayload, and
 * features) and returns it as an {@link AdbStlsResult} so the caller can construct a
 * pre-authenticated {@code AdbConnection} without sending another A_CNXN.
 *
 * The SSLContext must be configured with the ADB RSA key pair (via {@link AdbTlsContext}).
 * The device identifies clients by the RSA public key registered during pairing — using
 * a different key than the paired one will cause SSLV3_ALERT_CERTIFICATE_UNKNOWN.
 */
final class AdbStlsUpgrade {

    private static final String TAG = "AdbStlsUpgrade";

    // ADB wire protocol constants — only the subset needed for the STLS probe.
    private static final int A_CNXN = 0x4E584E43;
    private static final int A_STLS = 0x534C5453;
    private static final int A_VERSION = 0x01000000;
    private static final int A_MAXDATA = 4096;
    private static final int A_STLS_VERSION = 0x01000000;
    private static final int HEADER_SIZE = 24;

    private AdbStlsUpgrade() {}

    /**
     * Result of the TLS upgrade: an authenticated socket plus the daemon's A_CNXN data.
     *
     * After TLS, the daemon sends A_CNXN with its protocol version, max payload size,
     * and connection banner (containing device properties and supported features).
     * These are captured here so the caller can create an AdbConnection in
     * pre-authenticated state without re-sending A_CNXN.
     */
    static final class AdbStlsResult {
        /** The TLS-wrapped socket, ready for ADB protocol messages. */
        final Socket socket;
        /** Server protocol version from the post-auth A_CNXN (e.g. 0x01000001). */
        final int version;
        /** Server max payload size from the post-auth A_CNXN. */
        final int maxPayloadSize;
        /** Raw A_CNXN payload bytes (banner string with features for AdbConnection to parse). */
        final byte[] connectionPayload;

        AdbStlsResult(Socket socket, int version, int maxPayloadSize, byte[] connectionPayload) {
            this.socket = socket;
            this.version = version;
            this.maxPayloadSize = maxPayloadSize;
            this.connectionPayload = connectionPayload;
        }
    }

    /**
     * Opens a socket to the ADB daemon and performs the TLS upgrade.
     *
     * Returns an {@link AdbStlsResult} containing the authenticated SSLSocket and
     * the daemon's post-auth A_CNXN data. The caller should use
     * {@code AdbConnection.connectPreAuth()} with this result instead of the normal
     * {@code AdbConnection.connect()} — sending another A_CNXN would reset the
     * daemon's transport state.
     *
     * @param host           ADB daemon host (typically "127.0.0.1")
     * @param port           ADB daemon port (discovered via mDNS)
     * @param sslContext     SSLContext configured with the ADB RSA key (from {@link AdbTlsContext})
     * @param connectTimeout socket connect timeout in milliseconds, 0 for infinite
     * @param socketTimeout  socket read timeout in milliseconds, 0 for infinite
     * @return an {@link AdbStlsResult} with the TLS socket and connection info
     * @throws IOException            if the socket or TLS handshake fails
     * @throws AdbConnectionException if the server does not require TLS (not wireless debugging)
     */
    static AdbStlsResult upgradeIfTlsRequired(String host, int port, SSLContext sslContext,
                                               int connectTimeout, int socketTimeout)
            throws IOException, AdbConnectionException {
        Socket socket = new Socket();
        socket.setTcpNoDelay(true);
        socket.setSoTimeout(socketTimeout);
        socket.connect(new InetSocketAddress(host, port), connectTimeout);

        try {
            DataOutputStream out = new DataOutputStream(socket.getOutputStream());
            DataInputStream in = new DataInputStream(socket.getInputStream());

            // Send A_CNXN to trigger the server's TLS requirement check.
            // If this is a wireless debugging port, the server responds with A_STLS.
            writeMessage(out, A_CNXN, A_VERSION, A_MAXDATA, "host::\0".getBytes());

            int command = readCommand(in);
            if (command != A_STLS) {
                socket.close();
                throw new AdbConnectionException(
                        "Server did not request TLS upgrade (got 0x" + Integer.toHexString(command)
                                + "). Use Dadb.create() for non-TLS connections.");
            }

            Log.d(TAG, "A_STLS received, upgrading to transport TLS...");
            writeMessage(out, A_STLS, A_STLS_VERSION, 0, null);

            SSLSocket sslSocket = (SSLSocket) sslContext.getSocketFactory()
                    .createSocket(socket, host, port, /* autoClose */ true);
            sslSocket.startHandshake();
            Log.i(TAG, "Transport TLS established on " + host + ":" + port);

            // After TLS with valid client cert, the daemon authenticates us and sends
            // A_CNXN (from adbd_wifi_secure_connect → send_connect). Read and capture
            // this CNXN — it contains version, maxPayload, and the features banner.
            // We must NOT send another A_CNXN: that would trigger handle_new_connection
            // on the daemon which calls handle_offline() + send_tls_request(), resetting
            // the authenticated transport.
            DataInputStream tlsIn = new DataInputStream(sslSocket.getInputStream());
            AdbMessageData cnxn = readMessage(tlsIn);

            if (cnxn.command != A_CNXN) {
                throw new IOException("Expected A_CNXN after TLS auth, got 0x"
                        + Integer.toHexString(cnxn.command));
            }

            Log.i(TAG, "Post-auth A_CNXN: version=0x" + Integer.toHexString(cnxn.arg0)
                    + " maxPayload=" + cnxn.arg1
                    + " banner=" + new String(cnxn.payload));

            return new AdbStlsResult(sslSocket, cnxn.arg0, cnxn.arg1, cnxn.payload);

        } catch (Throwable t) {
            socket.close();
            throw t;
        }
    }

    /**
     * Parsed fields from a single ADB protocol message.
     */
    private static final class AdbMessageData {
        final int command;
        final int arg0;
        final int arg1;
        final byte[] payload;

        AdbMessageData(int command, int arg0, int arg1, byte[] payload) {
            this.command = command;
            this.arg0 = arg0;
            this.arg1 = arg1;
            this.payload = payload;
        }
    }

    /**
     * Reads a single ADB message header and returns the command field, discarding the payload.
     *
     * This consumes exactly one ADB protocol message (24-byte header + payload bytes)
     * from the stream.
     */
    private static int readCommand(DataInputStream in) throws IOException {
        byte[] header = new byte[HEADER_SIZE];
        in.readFully(header);
        ByteBuffer buf = ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN);
        int command = buf.getInt(0);
        int dataLength = buf.getInt(12);
        if (dataLength > 0) {
            in.readFully(new byte[dataLength]);
        }
        return command;
    }

    /**
     * Reads a single ADB message header and payload, returning all fields.
     *
     * Used for the post-auth A_CNXN where we need version, maxPayload, and the
     * features banner.
     */
    private static AdbMessageData readMessage(DataInputStream in) throws IOException {
        byte[] header = new byte[HEADER_SIZE];
        in.readFully(header);
        ByteBuffer buf = ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN);
        int command = buf.getInt(0);
        int arg0 = buf.getInt(4);
        int arg1 = buf.getInt(8);
        int dataLength = buf.getInt(12);
        byte[] payload = new byte[dataLength];
        if (dataLength > 0) {
            in.readFully(payload);
        }
        return new AdbMessageData(command, arg0, arg1, payload);
    }

    /**
     * Writes a single ADB message (24-byte header + optional payload) to the stream.
     *
     * ADB header layout (all little-endian uint32):
     * [command] [arg0] [arg1] [data_length] [data_checksum] [magic]
     */
    private static void writeMessage(DataOutputStream out, int command, int arg0, int arg1, byte[] data)
            throws IOException {
        int dataLength = (data != null) ? data.length : 0;
        int checksum = 0;
        if (data != null) {
            for (byte b : data) {
                checksum += (b & 0xFF);
            }
        }

        ByteBuffer header = ByteBuffer.allocate(HEADER_SIZE).order(ByteOrder.LITTLE_ENDIAN);
        header.putInt(command);
        header.putInt(arg0);
        header.putInt(arg1);
        header.putInt(dataLength);
        header.putInt(checksum);
        header.putInt(command ^ 0xFFFFFFFF);

        out.write(header.array());
        if (data != null) {
            out.write(data);
        }
        out.flush();
    }

}

