package ly.com.tahaben.farhan_rescue.capture

import ly.com.tahaben.farhan_rescue.adb.*
import ly.com.tahaben.farhan_rescue.input.SourceTarget
import ly.com.tahaben.farhan_rescue.storage.JobDirectory
import java.io.IOException
import java.io.OutputStream
import java.security.DigestOutputStream
import java.security.MessageDigest

/** Why a bridge operation ended without a result. Reasons only: no path, value or output text. */
enum class FailureCode {
    BAD_REQUEST,
    BUSY,
    PAIR_FAILED,
    CONNECT_FAILED,
    PAIRING_REQUIRED,
    IDENTITY_FAILED,
    RUN_AS_NOT_DEBUGGABLE,
    RUN_AS_PACKAGE_NOT_FOUND,
    RUN_AS_USER_REJECTED,
    RUN_AS_UNAVAILABLE,
    RUN_AS_UNRECOGNIZED,
    UID_USER_MISMATCH,
    FORCE_STOP_FAILED,
    LISTING_FAILED,
    STAT_FAILED,
    NOTHING_TO_EXPORT,
    SIDECAR_WITHOUT_DATABASE,
    TOO_MANY_WIDGET_FILES,
    FILE_TOO_LARGE,
    CAPTURE_TOO_LARGE,
    OUTPUT_BUDGET_EXCEEDED,
    COPY_INCOMPLETE,
    DIGEST_MISMATCH,
    SOURCE_CHANGED,
    STORAGE_FAILED,
    CONVERSION_FAILED,
    TIMED_OUT,
    BRIDGE_DIED,
    CANCELLED,
    INTERNAL,
}

class CaptureException(val code: FailureCode) : RuntimeException(code.name)

enum class Integrity { SHA256, SIZE_ONLY }

enum class Stage { PROBING, READING_VERSION, LISTING, STOPPING_SOURCE, COPYING, VERIFYING }

data class Progress(val stage: Stage, val done: Int = 0, val total: Int = 0)

/** What a check found. Counts and flags only. */
data class CheckFacts(
    val uid: Long,
    val version: PackageVersion?,
    val plannedFileCount: Int,
    val hasDatabase: Boolean,
    val usedPreferencesBackup: Boolean,
)

data class CaptureFacts(
    val uid: Long,
    val version: PackageVersion?,
    /** Local paths (see [RemoteFiles]) of every file copied into the job directory. */
    val localPaths: List<String>,
    val usedPreferencesBackup: Boolean,
    val integrity: Integrity,
)

/**
 * The whole device-side sequence, over a [RemoteShell]. Pure JVM so the order and refusals are unit-tested with a
 * fake device.
 *
 * Invariants:
 *  - CLAIM(run-as-first): nothing is listed, stopped or copied until `run-as ... id -u` has returned a uid whose
 *    user part equals the requested user [CaptureEngineTest].
 *  - CLAIM(stop-once): the only write to the source is one `am force-stop`, and only in [export], after the probe
 *    and before any copy. [check] never stops anything [CaptureEngineTest].
 *  - CLAIM(absent-vs-failed): a directory is "absent" only when its parent's successful listing lacks it. A
 *    listing, stat or stop without the sentinel is a failure, never an empty result [CaptureEngineTest].
 *  - CLAIM(bounded-capture): sizes come from `stat`; each file is bounded by its role, widget files and the whole
 *    capture by aggregate caps, all checked before the first copy; each copy stops at its stat size; text outputs
 *    share one [OUTPUT_BUDGET_BYTES] budget [CaptureEngineTest].
 *  - CLAIM(source-stable): metadata before and after copying, and the file set before and after, must be equal;
 *    otherwise [FailureCode.SOURCE_CHANGED] and nothing is returned [CaptureEngineTest].
 *  - CLAIM(copy-verified): each copy has exactly its stat length and, when `sha256sum` answers, its digest.
 */
class CaptureEngine(
    private val shell: RemoteShell,
    private val reportProgress: (Progress) -> Unit = {},
    private val throwIfCancelled: () -> Unit = {},
) {
    private var outputBudget = OUTPUT_BUDGET_BYTES

    fun check(target: SourceTarget): CheckFacts {
        val uid = probe(target)
        val version = readVersion(target)
        val plan = planned(target)
        return CheckFacts(
            uid, version, plan.files.size,
            plan.files.any { it.role == FileRole.DATABASE }, plan.usedPreferencesBackup,
        )
    }

    fun export(target: SourceTarget, job: JobDirectory): CaptureFacts {
        val uid = probe(target)
        val version = readVersion(target)
        stopSource(target)
        val plan = planned(target)
        val before = statAll(target, plan.files)
        enforceAggregateBounds(plan.files, before)
        var allHashed = true
        plan.files.forEachIndexed { index, file ->
            throwIfCancelled()
            reportProgress(Progress(Stage.COPYING, index, plan.files.size))
            if (!copyOne(target, file, before.getValue(file), job)) allHashed = false
        }
        reportProgress(Progress(Stage.VERIFYING, plan.files.size, plan.files.size))
        val after = statAll(target, plan.files)
        if (after != before) throw CaptureException(FailureCode.SOURCE_CHANGED)
        val replan = planned(target)
        if (replan.files.map { it.remotePath } != plan.files.map { it.remotePath }) throw CaptureException(FailureCode.SOURCE_CHANGED)
        return CaptureFacts(uid, version, plan.files.map { it.localPath }, plan.usedPreferencesBackup,
            if (allHashed) Integrity.SHA256 else Integrity.SIZE_ONLY)
    }

    private fun probe(target: SourceTarget): Long {
        throwIfCancelled()
        reportProgress(Progress(Stage.PROBING))
        return when (val probe = AdbOutput.parseUidProbe(text(AdbCommand.ProbeUid(target), 4096))) {
            is UidProbe.Uid -> {
                if (!AdbOutput.uidMatchesUser(probe.uid, target.user.value)) throw CaptureException(FailureCode.UID_USER_MISMATCH)
                probe.uid
            }
            is UidProbe.Failed -> throw CaptureException(when (probe.reason) {
                RunAsFailure.NOT_DEBUGGABLE -> FailureCode.RUN_AS_NOT_DEBUGGABLE
                RunAsFailure.PACKAGE_NOT_FOUND, RunAsFailure.NOT_AN_APPLICATION -> FailureCode.RUN_AS_PACKAGE_NOT_FOUND
                RunAsFailure.USER_REJECTED -> FailureCode.RUN_AS_USER_REJECTED
                RunAsFailure.UNAVAILABLE -> FailureCode.RUN_AS_UNAVAILABLE
                RunAsFailure.UNRECOGNIZED -> FailureCode.RUN_AS_UNRECOGNIZED
            })
        }
    }

    /** Informational only: a dump that does not answer yields null, and the file says the version is unknown. */
    private fun readVersion(target: SourceTarget): PackageVersion? {
        throwIfCancelled()
        reportProgress(Progress(Stage.READING_VERSION))
        val interesting = ArrayList<String>()
        try {
            shell.lines(AdbCommand.ReadVersion(target.packageName), minOf(outputBudget, VERSION_DUMP_BYTES)) { line ->
                spend(line.length + 1)
                val trimmed = line.trim()
                if (trimmed.startsWith("versionCode=") || trimmed.startsWith("versionName=")) interesting += trimmed
                AdbOutput.parseVersion(interesting.asSequence()) == null && interesting.size < 16
            }
        } catch (failure: OutputTooLarge) {
        } catch (failure: IOException) {
        }
        return AdbOutput.parseVersion(interesting.asSequence())
    }

    private fun stopSource(target: SourceTarget) {
        throwIfCancelled()
        reportProgress(Progress(Stage.STOPPING_SOURCE))
        if (AdbOutput.linesBeforeSentinel(text(AdbCommand.ForceStop(target), 4096)) == null) {
            throw CaptureException(FailureCode.FORCE_STOP_FAILED)
        }
    }

    private fun planned(target: SourceTarget): CapturePlan.Planned {
        throwIfCancelled()
        reportProgress(Progress(Stage.LISTING))
        return when (val plan = CapturePlanner.plan(listings(target))) {
            is CapturePlan.Planned -> plan
            is CapturePlan.Refused -> throw CaptureException(when (plan.problem) {
                PlanProblem.NOTHING_TO_EXPORT -> FailureCode.NOTHING_TO_EXPORT
                PlanProblem.SIDECAR_WITHOUT_DATABASE -> FailureCode.SIDECAR_WITHOUT_DATABASE
                PlanProblem.TOO_MANY_WIDGET_FILES -> FailureCode.TOO_MANY_WIDGET_FILES
            })
        }
    }

    private fun listings(target: SourceTarget): Map<RemoteDirectory, List<String>> {
        val root = list(target, RemoteDirectory.ROOT).toSet()
        val filesDirectory = if ("files" in root) list(target, RemoteDirectory.FILES).toSet() else emptySet()
        return mapOf(
            RemoteDirectory.SHARED_PREFS to listIfPresent(target, RemoteDirectory.SHARED_PREFS, "shared_prefs" in root),
            RemoteDirectory.DATA_STORE to listIfPresent(target, RemoteDirectory.DATA_STORE, "datastore" in filesDirectory),
            RemoteDirectory.DATABASES to listIfPresent(target, RemoteDirectory.DATABASES, "databases" in root),
        )
    }

    private fun listIfPresent(target: SourceTarget, directory: RemoteDirectory, present: Boolean) =
        if (present) list(target, directory) else emptyList()

    private fun list(target: SourceTarget, directory: RemoteDirectory): List<String> =
        AdbOutput.linesBeforeSentinel(text(AdbCommand.ListDirectory(target, directory), LISTING_BYTES))
            ?: throw CaptureException(FailureCode.LISTING_FAILED)

    private fun statAll(target: SourceTarget, files: List<RemoteFile>): Map<RemoteFile, FileFingerprint> {
        throwIfCancelled()
        return files.associateWith { file ->
            AdbOutput.parseStat(text(AdbCommand.StatFile(target, file), STAT_BYTES)) ?: throw CaptureException(FailureCode.STAT_FAILED)
        }
    }

    private fun enforceAggregateBounds(files: List<RemoteFile>, sizes: Map<RemoteFile, FileFingerprint>) {
        var total = 0L
        var widgets = 0L
        for (file in files) {
            val size = sizes.getValue(file).sizeBytes
            if (size > file.role.maxBytes) throw CaptureException(FailureCode.FILE_TOO_LARGE)
            total += size
            if (file.role == FileRole.WIDGET_STATE) widgets += size
        }
        if (widgets > RemoteFiles.MAX_WIDGET_TOTAL_BYTES || total > RemoteFiles.MAX_TOTAL_BYTES) {
            throw CaptureException(FailureCode.CAPTURE_TOO_LARGE)
        }
    }

    /** Returns true when the digest was verified, false when the device had no usable `sha256sum`. */
    private fun copyOne(target: SourceTarget, file: RemoteFile, fingerprint: FileFingerprint, job: JobDirectory): Boolean {
        val digest = MessageDigest.getInstance("SHA-256")
        val copied = try {
            job.sink(file.localPath).use { sink ->
                shell.copy(AdbCommand.CopyFile(target, file), DigestOutputStream(sink as OutputStream, digest), fingerprint.sizeBytes)
            }
        } catch (failure: OutputTooLarge) {
            throw CaptureException(FailureCode.SOURCE_CHANGED)
        } catch (failure: IOException) {
            throw CaptureException(FailureCode.STORAGE_FAILED)
        }
        if (copied != fingerprint.sizeBytes) throw CaptureException(FailureCode.COPY_INCOMPLETE)
        val remoteDigest = AdbOutput.parseSha256(text(AdbCommand.HashFile(target, file), STAT_BYTES)) ?: return false
        val localDigest = digest.digest().joinToString("") { "%02x".format(it) }
        if (remoteDigest != localDigest) throw CaptureException(FailureCode.DIGEST_MISMATCH)
        return true
    }

    private fun text(command: AdbCommand, maxBytes: Int): String {
        val output = try {
            shell.text(command, minOf(maxBytes, outputBudget))
        } catch (failure: OutputTooLarge) {
            throw CaptureException(FailureCode.OUTPUT_BUDGET_EXCEEDED)
        }
        spend(output.length)
        return output
    }

    private fun spend(bytes: Int) {
        outputBudget -= bytes
        if (outputBudget < 0) throw CaptureException(FailureCode.OUTPUT_BUDGET_EXCEEDED)
    }

    companion object {
        const val OUTPUT_BUDGET_BYTES = 16 shl 20
        const val VERSION_DUMP_BYTES = 8 shl 20
        const val LISTING_BYTES = 64 shl 10
        const val STAT_BYTES = 4 shl 10
    }
}

package ly.com.tahaben.farhan_rescue.bridge

import ly.com.tahaben.farhan_rescue.adb.PackageVersion
import ly.com.tahaben.farhan_rescue.capture.*
import ly.com.tahaben.farhan_rescue.input.*

enum class OperationKind { PAIR, CHECK, EXPORT }

/**
 * What the UI may ask the bridge. There is no free-text command: the bridge decodes into these types, and every
 * field is re-validated there (CLAIM(bridge-revalidates): a caller bypassing the form still cannot reach a
 * non-loopback host, a bad package or a bad port [BridgeProtocolTest]).
 */
sealed interface BridgeRequest {
    val kind: OperationKind

    data class Pair(val host: LoopbackHost, val port: TcpPort, val code: PairingCode) : BridgeRequest {
        override val kind get() = OperationKind.PAIR
    }

    data class Check(val host: LoopbackHost, val port: TcpPort, val target: SourceTarget) : BridgeRequest {
        override val kind get() = OperationKind.CHECK
    }

    data class Export(val host: LoopbackHost, val port: TcpPort, val target: SourceTarget, val jobId: JobId) : BridgeRequest {
        override val kind get() = OperationKind.EXPORT
    }
}

sealed interface BridgeEvent {
    data class Hello(val pid: Int) : BridgeEvent
    data class ProgressUpdate(val progress: Progress) : BridgeEvent
    data object Paired : BridgeEvent
    data class Checked(val facts: CheckFacts) : BridgeEvent
    data class Captured(val facts: CaptureFacts) : BridgeEvent
    data class Failed(val code: FailureCode) : BridgeEvent
}

/** Binder message ids. */
object BridgeMessages {
    const val REGISTER = 1
    const val REQUEST = 2
    const val CANCEL = 3
    const val EVENT = 101
}

/**
 * Flat key-value form of requests and events, the only thing that crosses Binder. Values are String, Int, Long or a
 * list of String; the Android layer copies them into a Bundle. CLAIM(small-binder): the largest event carries at
 * most [MAX_LOCAL_PATHS] short path strings, far below the 1 MiB transaction limit; recovered settings never cross
 * Binder, they stay in the private job directory [BridgeProtocolTest].
 */
typealias Wire = Map<String, Any?>

object BridgeWire {
    const val MAX_LOCAL_PATHS = 300
    private const val KIND = "kind"

    /** Request fields plus the UI's operation id, which the bridge echoes on every event of that operation. */
    fun encode(request: BridgeRequest, operationId: Long): Wire = requestFields(request) + ("op" to operationId)

    /** The operation id carried by a request or an event; null when absent or not a Long. */
    fun operationOf(wire: Wire): Long? = wire["op"] as? Long

    private fun requestFields(request: BridgeRequest): Wire = when (request) {
        is BridgeRequest.Pair -> mapOf(KIND to "pair", "host" to request.host.address, "port" to request.port.value.toString(), "code" to request.code.reveal())
        is BridgeRequest.Check -> mapOf(KIND to "check", "host" to request.host.address, "port" to request.port.value.toString(),
            "package" to request.target.packageName.value, "user" to request.target.user.value.toString())
        is BridgeRequest.Export -> mapOf(KIND to "export", "host" to request.host.address, "port" to request.port.value.toString(),
            "package" to request.target.packageName.value, "user" to request.target.user.value.toString(), "job" to request.jobId.value)
    }

    /** Null for anything that is not exactly a valid request. Never throws on hostile input. */
    fun decodeRequest(wire: Wire): BridgeRequest? {
        fun text(key: String): String? = wire[key] as? String
        val host = LoopbackHost.parse(text("host") ?: return null).orNull() ?: return null
        val port = TcpPort.parse(text("port") ?: return null).orNull() ?: return null
        fun target(): SourceTarget? {
            val pkg = PackageName.parse(text("package") ?: return null).orNull() ?: return null
            val user = AndroidUserId.parse(text("user") ?: return null).orNull() ?: return null
            return SourceTarget(pkg, user)
        }
        return when (text(KIND)) {
            "pair" -> BridgeRequest.Pair(host, port, PairingCode.parse(text("code") ?: return null).orNull() ?: return null)
            "check" -> BridgeRequest.Check(host, port, target() ?: return null)
            "export" -> BridgeRequest.Export(host, port, target() ?: return null, JobId.parse(text("job") ?: return null).orNull() ?: return null)
            else -> null
        }
    }

    fun encode(event: BridgeEvent, operationId: Long? = null): Wire =
        eventFields(event).let { if (operationId != null) it + ("op" to operationId) else it }

    private fun eventFields(event: BridgeEvent): Wire = when (event) {
        is BridgeEvent.Hello -> mapOf(KIND to "hello", "pid" to event.pid)
        is BridgeEvent.ProgressUpdate -> mapOf(KIND to "progress", "stage" to event.progress.stage.name,
            "done" to event.progress.done, "total" to event.progress.total)
        BridgeEvent.Paired -> mapOf(KIND to "paired")
        is BridgeEvent.Checked -> mapOf(KIND to "checked", "uid" to event.facts.uid,
            "versionName" to (event.facts.version?.name ?: ""), "versionCode" to (event.facts.version?.code ?: -1L),
            "files" to event.facts.plannedFileCount, "database" to if (event.facts.hasDatabase) 1 else 0,
            "backup" to if (event.facts.usedPreferencesBackup) 1 else 0)
        is BridgeEvent.Captured -> mapOf(KIND to "captured", "uid" to event.facts.uid,
            "versionName" to (event.facts.version?.name ?: ""), "versionCode" to (event.facts.version?.code ?: -1L),
            "paths" to event.facts.localPaths, "backup" to if (event.facts.usedPreferencesBackup) 1 else 0,
            "integrity" to event.facts.integrity.name)
        is BridgeEvent.Failed -> mapOf(KIND to "failed", "code" to event.code.name)
    }

    /** Null for a malformed event; the UI then treats the bridge as failed (BRIDGE_DIED), never guesses. */
    fun decodeEvent(wire: Wire): BridgeEvent? = try {
        fun int(key: String) = wire[key] as? Int
        fun long(key: String) = wire[key] as? Long
        fun string(key: String) = wire[key] as? String
        fun version(): PackageVersion? {
            val name = string("versionName") ?: return null
            val code = long("versionCode") ?: return null
            return if (name.isEmpty() || code < 0) null else PackageVersion(name, code)
        }
        when (string(KIND)) {
            "hello" -> int("pid")?.takeIf { it > 0 }?.let(BridgeEvent::Hello)
            "progress" -> BridgeEvent.ProgressUpdate(Progress(Stage.valueOf(string("stage")!!), int("done")!!, int("total")!!))
            "paired" -> BridgeEvent.Paired
            "checked" -> BridgeEvent.Checked(CheckFacts(long("uid")!!, version(), int("files")!!, int("database") == 1, int("backup") == 1))
            "captured" -> {
                val paths = (wire["paths"] as List<*>).map { it as String }
                if (paths.size > MAX_LOCAL_PATHS) null
                else BridgeEvent.Captured(CaptureFacts(long("uid")!!, version(), paths, int("backup") == 1, Integrity.valueOf(string("integrity")!!)))
            }
            "failed" -> BridgeEvent.Failed(FailureCode.valueOf(string("code")!!))
            else -> null
        }
    } catch (failure: Exception) {
        null
    }
}
class RawJobStore(private val root: File) {
    fun create(jobId: JobId): JobDirectory {
        val directory = File(root, jobId.value)
        check(!directory.exists()) { "job directory already exists" }
        check(directory.mkdirs()) { "cannot create job directory" }
        return JobDirectory(directory)
    }

    fun open(jobId: JobId): JobDirectory? = File(root, jobId.value).takeIf { it.isDirectory }?.let(::JobDirectory)

    fun delete(jobId: JobId) {
        File(root, jobId.value).deleteRecursively()
    }

    /** Next-startup sweep and every cancel: removes every job, finished or not. */
    fun deleteAll() {
        root.listFiles()?.forEach { it.deleteRecursively() }
    }

    fun isEmpty(): Boolean = root.listFiles().isNullOrEmpty()
}

class JobDirectory internal constructor(val directory: File) {
    /** Opens a new file for [localPath]. Throws if the path is not an allowlisted local path. */
    fun sink(localPath: String): OutputStream {
        requireNotNull(RemoteFiles.classifyLocal(localPath)) { "path is not allowlisted" }
        val target = File(directory, localPath)
        check(target.parentFile!!.isDirectory || target.parentFile!!.mkdirs()) { "cannot create directory" }
        check(!target.exists()) { "file already exists" }
        return FileOutputStream(target)
    }

    /** The file for an allowlisted path, or null if absent or not allowlisted. */
    fun file(localPath: String): File? {
        if (RemoteFiles.classifyLocal(localPath) == null) return null
        return File(directory, localPath).takeIf { it.isFile }
    }
}

/** The converted, validated portable file waiting to be saved. Not raw data: it survives a cancelled save. */
class PendingExportStore(private val file: File) {
    fun save(bytes: ByteArray) = AtomicFiles.write(file, bytes)
    fun load(maxBytes: Int = 1 shl 20): ByteArray? = AtomicFiles.read(file, maxBytes)
    fun clear() = AtomicFiles.delete(file)
}

/**
 * The throwaway ADB client identity (RSA key + self-signed certificate), in `no_backup` storage only.
 * CLAIM(short-lived-identity): [load] refuses an identity older than [MAX_AGE_MILLIS] and erases it; erase on
 * completed capture, reset and cancel is the caller's job [PrivateFilesTest].
 */

 *    the field is cleared as soon as the request is sent.
 */
class RescueActivity : Activity() {
    private enum class Phase { IDLE, WORKING, CONVERTING, REVIEW, SAVING, SAVED }

    private lateinit var paths: RescuePaths
    private val main = Handler(Looper.getMainLooper())
    private val workers = Executors.newSingleThreadExecutor { Thread(it, "rescue-worker").apply { isDaemon = true } }
    private val converter = RescueConverter()
    private var destroyed = false

    private var phase = Phase.IDLE
    private var statusText: String = ""
    private var preview: ExportPreview? = null
    private var copiedWithoutDigest = false
    private var currentJob: JobId? = null
    private var currentTarget: SourceTarget? = null
    private var conversionToken = REDACTED

    private var bridgeBinder: IBinder? = null
    private var bridge: Messenger? = null
    private var generation = 0L
    private var rebindPending = false
    private val session = BridgeSession(Process.myPid(), { pid -> Process.killProcess(pid) }, { bridgeBinder?.pingBinder() == true })
    private val tracker = OperationTracker(session, HandlerScheduler(main), SystemClock::elapsedRealtime, onTimedOut = ::onTimedOut)
    private val connection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName, service: IBinder) {
            bridgeBinder = service
            bridge = Messenger(service)
            val connectionGeneration = session.onBound()
            generation = connectionGeneration
            // A fresh reply Messenger per connection, closed over its generation: a queued reply from an earlier
            // connection can never be mistaken for this one's [EventRouting].
            val inbound = Messenger(Handler(Looper.getMainLooper()) { message -> onBridgeMessage(message, connectionGeneration); true })
            sendToBridge(Message.obtain(null, BridgeMessages.REGISTER).apply { replyTo = inbound })
        }
        override fun onServiceDisconnected(name: ComponentName) = lostBridge()
        override fun onBindingDied(name: ComponentName) = lostBridge()
        override fun onNullBinding(name: ComponentName) = lostBridge()
    }

    private lateinit var packageField: EditText
    private lateinit var userField: EditText
    private lateinit var pairingPortField: EditText
    private lateinit var pairingCodeField: EditText
    private lateinit var connectPortField: EditText
    private lateinit var confirmStop: CheckBox
    private lateinit var statusView: TextView
    private lateinit var progressBar: ProgressBar
    private lateinit var reviewView: TextView
    private lateinit var savedView: TextView
    private val setupViews = mutableListOf<View>()
    private val actionButtons = mutableListOf<Button>()
    private lateinit var cancelButton: Button
    private lateinit var saveButton: Button
    private lateinit var finishButton: Button

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        paths = RescuePaths(this)
        setContentView(buildLayout())
        restorePendingBackup()
        render()
        bindBridge()
    }

    override fun onDestroy() {
        destroyed = true
        val wasRunning = tracker.cancel()
        if (wasRunning) sendToBridge(Message.obtain(null, BridgeMessages.CANCEL))
        conversionToken++
        paths.rawJobs.deleteAll()
        if (wasRunning || isFinishing) paths.identity.erase()
        try { unbindService(connection) } catch (ignored: IllegalArgumentException) { }
        workers.shutdownNow()
        super.onDestroy()
    }

    // ---- bridge plumbing -------------------------------------------------------------------------------------

    private fun bindBridge() {
        bindService(Intent(this, AdbBridgeService::class.java), connection, Context.BIND_AUTO_CREATE)
        statusText = getString(R.string.bridge_starting)
    }

    private fun lostBridge() {
        session.onUnbound()
        bridgeBinder = null
        bridge = null
        if (tracker.cancel()) {
            paths.rawJobs.deleteAll()
            showFailure(FailureCode.BRIDGE_DIED)
        }
        if (!destroyed && !rebindPending) {
            rebindPending = true
            main.post {
                rebindPending = false
                if (destroyed) return@post
                try { unbindService(connection) } catch (ignored: IllegalArgumentException) { }
                bindBridge()
            }
        }
        render()
    }

    private fun sendToBridge(message: Message) {
        val target = bridge ?: return
        try { target.send(message) } catch (gone: RemoteException) { lostBridge() }
    }

    private fun start(request: BridgeRequest) {
        val operation = tracker.begin(request.kind)
        if (operation == null) {
            statusText = getString(if (session.isLive) R.string.failure_busy else R.string.bridge_starting)
            render()
            return
        }
        phase = Phase.WORKING
        statusText = getString(R.string.working)
        sendToBridge(Message.obtain(null, BridgeMessages.REQUEST).apply { data = BundleWire.toBundle(BridgeWire.encode(request, operation.id)) })
        render()
    }

    private fun onBridgeMessage(message: Message, connectionGeneration: Long) {
        if (message.what != BridgeMessages.EVENT) return
        val wire = BundleWire.fromBundle(message.data)
        val event = BridgeWire.decodeEvent(wire)
        if (event == null) {
            if (connectionGeneration == generation) failOperation(FailureCode.BRIDGE_DIED)
            return
        }
        if (!EventRouting.accept(event, connectionGeneration, generation, BridgeWire.operationOf(wire), tracker.inflight)) return
        when (event) {
            is BridgeEvent.Hello -> session.onHello(event.pid, generation).also {
                if (it && phase == Phase.IDLE && statusText == getString(R.string.bridge_starting)) statusText = ""
            }
            is BridgeEvent.ProgressUpdate -> {
                tracker.inflight?.let { tracker.progress(it.id) }
                val progress = event.progress
                statusText = if (progress.total > 0) getString(stageMessage(progress.stage), progress.done + 1, progress.total) else getString(stageMessage(progress.stage))
            }
            BridgeEvent.Paired -> finishOperation { statusText = getString(R.string.paired_ok) }
            is BridgeEvent.Checked -> finishOperation {
                val facts = event.facts
                val version = facts.version?.name ?: getString(R.string.checked_version_unknown)
                val database = getString(if (facts.hasDatabase) R.string.checked_database_yes else R.string.checked_database_no)
                statusText = getString(R.string.checked_ok, version, facts.plannedFileCount, database)
            }
            is BridgeEvent.Captured -> finishOperation { startConversion(event.facts) }
            is BridgeEvent.Failed -> failOperation(event.code)
        }
        render()
    }

    private inline fun finishOperation(then: () -> Unit) {
        tracker.inflight?.let { tracker.complete(it.id) }
        if (phase == Phase.WORKING) phase = Phase.IDLE
        then()
    }

    private fun failOperation(code: FailureCode) {
        val failed = tracker.inflight
        failed?.let { tracker.complete(it.id) }
        paths.rawJobs.deleteAll()
        // CLAIM(export-cleanup): a failed export leaves no raw copy and no pairing key; the source stays stopped until reopened.
        if (failed?.kind == OperationKind.EXPORT) { paths.identity.erase(); currentJob = null }
        showFailure(code)
        render()
    }

    private fun onTimedOut(operation: OperationTracker.Inflight) {
        currentJob = null
        paths.rawJobs.deleteAll()
        paths.identity.erase()
        showFailure(FailureCode.TIMED_OUT)
        render()
    }

    private fun showFailure(code: FailureCode) {
        phase = Phase.IDLE
        statusText = getString(failureMessage(code))
    }

    /** Cancel: end the bridge process (the only way to stop a blocked pairing), erase the key and every copy. */
    private fun cancelEverything() {
        sendToBridge(Message.obtain(null, BridgeMessages.CANCEL))
        tracker.cancel()
        conversionToken++
        paths.rawJobs.deleteAll()
        paths.identity.erase()
        showFailure(FailureCode.CANCELLED)
        render()
    }

    // ---- actions ---------------------------------------------------------------------------------------------

    private fun onPair() {
        val port = parsePort(pairingPortField) ?: return
        val code = PairingCode.parse(pairingCodeField.text.toString()).orNull()
        if (code == null) { pairingCodeField.error = getString(R.string.error_code); return }
        pairingCodeField.text.clear()
        start(BridgeRequest.Pair(LoopbackHost.IPV4, port, code))
    }

    private fun onCheck() {
        val target = parseTarget() ?: return
        val port = parsePort(connectPortField) ?: return
        start(BridgeRequest.Check(LoopbackHost.IPV4, port, target))
    }

    private fun onExport() {
        val target = parseTarget() ?: return
        val port = parsePort(connectPortField) ?: return
        if (!confirmStop.isChecked) return
        val job = JobId.random()
        currentJob = job
        currentTarget = target
        paths.pending.clear()
        start(BridgeRequest.Export(LoopbackHost.IPV4, port, target, job))
    }

    private fun parseTarget(): SourceTarget? {
        val pkg = when (val parsed = PackageName.parse(packageField.text.toString().trim())) {
            is Checked.Ok -> parsed.value
            is Checked.Rejected -> {
                packageField.error = getString(if (parsed.error == InputError.PACKAGE_IS_HELPER) R.string.error_package_helper else R.string.error_package)
                return null
            }
        }
        val user = AndroidUserId.parse(userField.text.toString().trim()).orNull()
        if (user == null) { userField.error = getString(R.string.error_user); return null }
        return SourceTarget(pkg, user)
    }

    private fun parsePort(field: EditText): TcpPort? =
        TcpPort.parse(field.text.toString().trim()).orNull().also { if (it == null) field.error = getString(R.string.error_port) }

    private fun openWirelessSettings() {
        try {
            startActivity(Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS))
        } catch (missing: Exception) {
            startActivity(Intent(Settings.ACTION_SETTINGS))
        }
    }

    // ---- conversion and saving -------------------------------------------------------------------------------

    private fun startConversion(facts: CaptureFacts) {
        copiedWithoutDigest = facts.integrity == ly.com.tahaben.farhan_rescue.capture.Integrity.SIZE_ONLY
        val job = currentJob
        val target = currentTarget
        if (job == null || target == null) { showFailure(FailureCode.INTERNAL); return }
        phase = Phase.CONVERTING
        statusText = getString(R.string.progress_converting)
        val token = ++conversionToken
        workers.execute {
            val result = try {
                val directory = paths.rawJobs.open(job)
                if (directory == null) ConversionResult.Failed(ly.com.tahaben.farhan_rescue.convert.ConversionFailure.FILES_MISSING)
                else converter.convert(directory, facts, target)
            } catch (failure: Exception) {
                ConversionResult.Failed(ly.com.tahaben.farhan_rescue.convert.ConversionFailure.COPY_UNREADABLE)
            } finally {
                paths.rawJobs.delete(job)
            }
            val stored = (result as? ConversionResult.Ready)?.let { ready ->
                try { paths.pending.save(ready.fileBytes); true } catch (failure: Exception) { false }
            } ?: true
            main.post {
                if (destroyed || token != conversionToken) { paths.pending.clear(); return@post }
                currentJob = null

