/** What a tar archive holds. Counts only: names never leave this scan. */
data class TarIndex(val entries: Int, val files: Int, val fileBytes: Long) {
    class Malformed(reason: String) : IOException(reason)

    companion object {
        const val MAX_ENTRIES = 200_000
        private const val BLOCK = 512

        /**
         * Walks [input] header by header, skipping file contents, and proves the archive is whole: every header's
         * checksum is right, every entry's data is fully present, and the end-of-archive zero block was reached.
         * `exec:` carries no exit status, so a `tar` that died halfway can only be told from a finished one this way.
         *
         * Understands what Android's toybox `tar` writes (old GNU and ustar headers) plus the long-name (`L`, `K`)
         * and pax (`x`, `g`) records, which carry metadata and are not counted as entries.
         */
        fun scan(input: InputStream): TarIndex {
            var entries = 0
            var files = 0
            var fileBytes = 0L
            val header = ByteArray(BLOCK)
            while (true) {
                if (!readBlock(input, header)) throw Malformed("archive ends without its end marker")
                if (header.all { it == 0.toByte() }) return TarIndex(entries, files, fileBytes)
                if (checksum(header) != parseNumber(header, 148, 8)) throw Malformed("header checksum mismatch")
                val size = parseNumber(header, 124, 12)
                if (size < 0) throw Malformed("negative size")
                val type = header[156].toInt().toChar()
                skip(input, roundUp(size))
                when (type) {
                    'L', 'K', 'x', 'g' -> Unit
                    '0', '\u0000', '7' -> { files++; fileBytes += size; entries++ }
                    else -> entries++
                }
                if (entries > MAX_ENTRIES) throw Malformed("too many entries")
            }
        }

        private fun readBlock(input: InputStream, into: ByteArray): Boolean {
            var done = 0
            while (done < BLOCK) {
                val n = input.read(into, done, BLOCK - done)
                if (n < 0) return false
                done += n
            }
            return true
        }

        private fun skip(input: InputStream, count: Long) {
            var left = count
            val scratch = ByteArray(8192)
            while (left > 0) {
                val skipped = input.skip(left)
                if (skipped > 0) { left -= skipped; continue }
                val n = input.read(scratch, 0, minOf(scratch.size.toLong(), left).toInt())
                if (n < 0) throw Malformed("archive ends inside a file")
                left -= n
            }
        }

        private fun roundUp(size: Long): Long = (size + BLOCK - 1) / BLOCK * BLOCK

        /** The checksum is the sum of every header byte with the checksum field itself read as spaces. */
        private fun checksum(header: ByteArray): Long {
            var sum = 0L
            for (i in header.indices) sum += if (i in 148 until 156) 0x20 else header[i].toLong() and 0xff
            return sum
        }

        /** An octal field, or GNU base-256 when the top bit of the first byte is set. */
        private fun parseNumber(header: ByteArray, offset: Int, length: Int): Long {
            if (header[offset].toInt() and 0x80 != 0) {
                var value = (header[offset].toLong() and 0x7f)
                for (i in 1 until length) value = (value shl 8) or (header[offset + i].toLong() and 0xff)
                return value
            }
            var value = 0L
            var seen = false
            for (i in 0 until length) {
                val c = header[offset + i].toInt().toChar()
                when {
                    c in '0'..'7' -> { value = value * 8 + (c - '0'); seen = true }
                    seen || c == '\u0000' && i > 0 -> return if (seen) value else 0
                    c == ' ' -> Unit
                    else -> throw Malformed("bad number field")
                }
            }
            return value
        }
    }
}
